res:http://www.w3.org/ns/prov#PrimarySource | w3c/rdf+resource | 0, 2400 | RdfResourcePayload { "iri": "http://www.w3.org/ns/prov#PrimarySource", "display": ":PrimarySource", "typeBadges": [ "owl:Class" ], "rows": [ { "predicate": "rdfs:comment", "value": "An instance of prov:PrimarySource provides additional descriptions about the binary prov:hadPrimarySource relation from some secondary prov:Entity to an earlier, primary prov:Entity. For example, :blog prov:hadPrimarySource :newsArticle; prov:qualifiedPrimarySource [ a prov:PrimarySource; prov:entity :newsArticle; :foo :bar ] .", "annotation": "@en" }, { "predicate": "rdfs:label", "value": "PrimarySource" }, { "predicate": ":category", "value": "qualified" }, { "predicate": ":component", "value": "derivations" }, { "predicate": ":definition", "value": "A primary source for a topic refers to something produced by some agent with direct experience and knowledge about the topic, at the time of the topic's study, without benefit from hindsight.

Because of the directness of primary sources, they 'speak for themselves' in ways that cannot be captured through the filter of secondary sources. As such, it is important for secondary sources to reference those primary sources from which they were derived, so that their reliability can be investigated.

A primary source relation is a particular case of derivation of secondary materials from their primary sources. It is recognized that the determination of primary sources can be up to interpretation, and should be done according to conventions accepted within the application's domain.", "annotation": "@en" }, { "predicate": ":dm", "value": "http://www.w3.org/TR/2013/REC-prov-dm-20130430/#term-primary-source", "annotation": "xsd:anyURI" }, { "predicate": ":n", "value": "http://www.w3.org/TR/2013/REC-prov-n-20130430/#expression-original-source", "annotation": "xsd:anyURI" } ] }
